// HasVehicle applies the HasEdge predicate on the "vehicle" edge.
func HasVehicle() predicate.VehicleDocument {
	return predicate.VehicleDocument(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, VehicleTable, VehicleColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasVehicleWith applies the HasEdge predicate on the "vehicle" edge with a given conditions (other predicates).
func HasVehicleWith(preds ...predicate.Vehicle) predicate.VehicleDocument {
	return predicate.VehicleDocument(func(s *sql.Selector) {
		step := newVehicleStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VehicleDocument) predicate.VehicleDocument {
	return predicate.VehicleDocument(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VehicleDocument) predicate.VehicleDocument {
	return predicate.VehicleDocument(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VehicleDocument) predicate.VehicleDocument {
	return predicate.VehicleDocument(sql.NotPredicates(p))
}
